/* eslint-disable @typescript-eslint/no-var-requires */
/*
 * NgpCraft: the GB Studio code that the V3 plugin bridge runs
 * (ngpcraft-v3/ngpcraft/plugin_bridge.cjs, docs/M7_PLUGINS.md), gathered by
 * esbuild into one file, so the packaged editor needs neither the GB Studio
 * sources nor TypeScript to compile a project's event plugins.
 *
 * The sources are the RELEASED GB Studio 4.3.2 (this fork changes some of
 * them): NGPCRAFT_GBSTUDIO_REFERENCE, or the pinned v4.3.2 release commit
 * (RELEASE), from this clone or fetched from GB Studio.
 * The ScriptBuilder signatures that the bridge reads from the TypeScript are
 * read here and written into the bundle. Target: the Node of the Electron that
 * runs it (main process, --ngpcraft-plugin-bridge).
 *
 *   node bundle-plugin-bridge.js <out.cjs>   (same sources as the packaging)
 */
const fs = require("fs-extra");
const Path = require("path");
const { execFileSync } = require("child_process");
const AdmZip = require("adm-zip");

const editorRoot = Path.join(__dirname, "../../../..");
const nodeModules = Path.join(editorRoot, "node_modules");
const loader = require(
  Path.join(
    editorRoot,
    "ngpcraft-v3",
    "ngpcraft",
    "plugin_bridge_gbstudio.cjs",
  ),
);
// The released GB Studio 4.3.2, pinned: tag v4.3.2 of chrismaltby/gb-studio.
const RELEASE = {
  tag: "v4.3.2",
  commit: "ccb891b2670134ba8237416772eea4ed09d34e1e",
  tree: "4220a0558084fcf789d6972de9ee4e4450c548f1",
  repository: "https://github.com/chrismaltby/gb-studio.git",
};
const git = (args, options = {}) =>
  execFileSync("git", ["-C", editorRoot, ...args], {
    maxBuffer: 1 << 30,
    ...options,
  });
// Node of the Electron that runs the bundle (Electron 22.3.27: Node 16.17.1,
// read from process.versions in its main process). Another Electron: check
// its Node and add it here.
const ELECTRON_NODE = { "22.3.27": "node16.17" };
const nodeTarget = () => {
  const electron = require(
    Path.join(nodeModules, "electron", "package.json"),
  ).version;
  if (!ELECTRON_NODE[electron]) {
    throw new Error(
      `plugin bridge: Node of Electron ${electron} unknown (bundle-plugin-bridge.js)`,
    );
  }
  return ELECTRON_NODE[electron];
};

// Root of a released GB Studio 4.3.2 tree (holds src/ and tsconfig.json).
const releasedSources = async () => {
  if (process.env.NGPCRAFT_GBSTUDIO_REFERENCE) {
    return process.env.NGPCRAFT_GBSTUDIO_REFERENCE;
  }
  const target = Path.join(
    editorRoot,
    ".bundle",
    "cache",
    `gb-studio-${RELEASE.tag}`,
  );
  if (!(await fs.pathExists(Path.join(target, "src")))) {
    // A shallow clone (CI) lacks the release commit: fetch it from GB Studio.
    try {
      git(["cat-file", "-e", `${RELEASE.commit}^{commit}`], {
        stdio: "ignore",
      });
    } catch (e) {
      git(["fetch", "--depth=1", RELEASE.repository, RELEASE.commit]);
    }
    const tree = git(["rev-parse", `${RELEASE.commit}^{tree}`])
      .toString()
      .trim();
    if (tree !== RELEASE.tree) {
      throw new Error(
        `GB Studio ${RELEASE.tag}: tree ${tree} is not the pinned ${RELEASE.tree}`,
      );
    }
    // Extracted beside, then moved: a cache is complete or absent.
    const archive = git([
      "archive",
      "--format=zip",
      RELEASE.commit,
      "src",
      "tsconfig.json",
    ]);
    const partial = `${target}.partial`;
    await fs.remove(partial);
    new AdmZip(archive).extractAllTo(partial, true);
    await fs.remove(target);
    await fs.move(partial, target);
  }
  return target;
};

const buildPluginBridge = async (outFile) => {
  const root = await releasedSources();
  const src = Path.join(root, "src");
  const ts = require(Path.join(nodeModules, "typescript"));
  const signatures = loader.signaturesOf(ts, src);
  // Fixed folder: the bundle names its modules by path (same input, same file).
  const entryDir = Path.join(
    editorRoot,
    ".bundle",
    "cache",
    "plugin-bridge-entry",
  );
  await fs.emptyDir(entryDir);
  try {
    for (const [name, source] of Object.entries(loader.bundleEntry())) {
      await fs.writeFile(Path.join(entryDir, name), source);
    }
    const esbuild = require(Path.join(nodeModules, "esbuild"));
    await fs.ensureDir(Path.dirname(outFile));
    const temporary = `${outFile}.tmp`;
    await esbuild.build({
      entryPoints: [Path.join(entryDir, "entry.ts")],
      bundle: true,
      absWorkingDir: editorRoot,
      platform: "node",
      target: nodeTarget(),
      format: "cjs",
      tsconfig: Path.join(root, "tsconfig.json"),
      nodePaths: [nodeModules],
      alias: loader.ALIASES,
      outfile: temporary,
      logLevel: "warning",
      banner: {
        js: `// GB Studio ${RELEASE.tag} (MIT, Chris Maltby) modules for the NgpCraft V3 plugin bridge; generated by src/lib/forge/hooks/bundle-plugin-bridge.js.`,
      },
      footer: {
        js: `module.exports.signatures = ${JSON.stringify(signatures)};`,
      },
    });
    await fs.move(temporary, outFile, { overwrite: true });
  } finally {
    await fs.remove(entryDir);
  }
  return outFile;
};

module.exports = { buildPluginBridge };

if (require.main === module) {
  buildPluginBridge(Path.resolve(process.argv[2])).then(
    (file) => console.log(`plugin bridge bundle: ${file}`),
    (e) => {
      console.error(e);
      process.exit(1);
    },
  );
}
